import { Types } from 'mongoose';
import jwt from 'jsonwebtoken';
import { User } from '../../models/User';
import { Patient } from '../../models/Patient';
import { Doctor } from '../../models/Doctor';

export interface TestUser {
  _id: Types.ObjectId;
  email: string;
  role: string;
  token: string;
}

export const createTestUser = async (role: string): Promise<TestUser> => {
  const user = await User.create({
    email: `${role}@test.com`,
    password: 'password123',
    role,
    firstName: 'Test',
    lastName: role.charAt(0).toUpperCase() + role.slice(1),
  });

  const token = jwt.sign(
    { userId: user._id, role: user.role },
    process.env.JWT_SECRET || 'test-secret-key',
    { expiresIn: '1h' }
  );

  return {
    _id: user._id,
    email: user.email,
    role: user.role,
    token,
  };
};

export const createTestPatient = async (userId: Types.ObjectId) => {
  return await Patient.create({
    userId,
    dateOfBirth: new Date('1990-01-01'),
    gender: 'male',
    address: {
      street: '123 Test St',
      city: 'Test City',
      state: 'Test State',
      zipCode: '12345',
    },
    phoneNumber: '1234567890',
    medicalHistory: [],
    allergies: [],
    medications: [],
  });
};

export const createTestDoctor = async (userId: Types.ObjectId) => {
  return await Doctor.create({
    userId,
    specialization: 'General Medicine',
    licenseNumber: 'TEST123',
    yearsOfExperience: 5,
    education: [
      {
        degree: 'MD',
        institution: 'Test University',
        year: 2015,
      },
    ],
    availability: {
      monday: { start: '09:00', end: '17:00' },
      tuesday: { start: '09:00', end: '17:00' },
      wednesday: { start: '09:00', end: '17:00' },
      thursday: { start: '09:00', end: '17:00' },
      friday: { start: '09:00', end: '17:00' },
    },
  });
};

export const generateAuthHeader = (token: string) => ({
  Authorization: `Bearer ${token}`,
});

export const expectError = (response: any, status: number, message: string) => {
  expect(response.status).toBe(status);
  expect(response.body).toHaveProperty('error');
  expect(response.body.error).toBe(message);
};

export const expectSuccess = (response: any, status: number) => {
  expect(response.status).toBe(status);
  expect(response.body).not.toHaveProperty('error');
}; 